import { useEffect, useMemo, useState } from 'react';
import { useForm, useWatch } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { format } from 'date-fns';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import PlusIcon from '@/components/icons/popups/PlusIcon';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import DayPickerInputForm from '@/components/forms/DayPickerInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { AddHolidayDialogFormValues, AddHolidayDialogSchema } from './add-holiday-dialog-schema';
import type { HolidayRangeRow } from './holiday-calendar-utils';
import { Textarea } from '@/components/ui/textarea';

const DEFAULT_REASON = 'إجازة رسمية — تقويم الموارد البشرية';

const STATUS_OPTIONS = [
    { value: 'pending', name: 'قيد المراجعة' },
    { value: 'approved', name: 'موافق عليه' },
    { value: 'rejected', name: 'مرفوض' },
];

type Props = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSaved?: () => void;
    editingHoliday?: HolidayRangeRow | null;
};

function parseLocalDate(isoYmd: string): Date {
    const [y, m, d] = isoYmd.split('-').map(Number);
    return new Date(y, (m || 1) - 1, d || 1);
}

function normalizeStatus(s: string | undefined): 'pending' | 'approved' | 'rejected' {
    if (s === 'approved' || s === 'rejected' || s === 'pending') return s;
    return 'pending';
}

export default function AddHolidayDialog({ open, onOpenChange, onSaved, editingHoliday = null }: Props) {
    const [submitting, setSubmitting] = useState(false);
    const isEdit = Boolean(editingHoliday?.id);
    const isEmployeeRequestEdit = Boolean(isEdit && editingHoliday && editingHoliday.employeeId != null);

    const form = useForm<AddHolidayDialogFormValues>({
        resolver: zodResolver(AddHolidayDialogSchema),
        defaultValues: {
            name: '',
            start_date: undefined as unknown as Date,
            end_date: undefined as unknown as Date,
            reason: '',
            status: 'pending',
            reject_reason: '',
        },
    });

    const watchedStatus = useWatch({ control: form.control, name: 'status' });

    useEffect(() => {
        if (!open) return;
        if (editingHoliday) {
            form.reset({
                name: editingHoliday.name,
                start_date: parseLocalDate(editingHoliday.start),
                end_date: parseLocalDate(editingHoliday.end),
                reason: editingHoliday.reason ?? '',
                status: normalizeStatus(editingHoliday.status),
                reject_reason: editingHoliday.rejectReason ?? '',
            });
        } else {
            form.reset({
                name: '',
                start_date: undefined as unknown as Date,
                end_date: undefined as unknown as Date,
                reason: '',
                status: 'pending',
                reject_reason: '',
            });
        }
    }, [open, editingHoliday, form]);

    const buildReasonText = (data: AddHolidayDialogFormValues) =>
        data.reason?.trim() || (isEmployeeRequestEdit ? '—' : DEFAULT_REASON);

    const postUpdate = async (data: AddHolidayDialogFormValues, status: 'pending' | 'approved' | 'rejected') => {
        if (!editingHoliday) return;
        if (status === 'rejected') {
            const rr = (data.reject_reason || '').trim();
            if (!rr) {
                toast.error('يرجى إدخال سبب الرفض', { className: 'font-cairo' });
                return;
            }
        }
        setSubmitting(true);
        try {
            const body: Record<string, string | boolean> = {
                vacation_type: data.name,
                start_date: format(data.start_date, 'yyyy-MM-dd'),
                end_date: format(data.end_date, 'yyyy-MM-dd'),
                reason: buildReasonText(data),
                status,
            };
            if (status === 'rejected' && (data.reject_reason || '').trim()) {
                body.reject_reason = (data.reject_reason || '').trim();
            }
            await apiPost({
                endpoint: endpoints.holiday.update + editingHoliday.id,
                body,
            });
            const msg =
                status === 'approved'
                    ? 'تمت الموافقة على الطلب'
                    : status === 'rejected'
                      ? 'تم رفض الطلب'
                      : 'تم تحديث حالة الطلب';
            toast.success(msg, { className: 'font-cairo' });
            onSaved?.();
            onOpenChange(false);
        } catch (e: unknown) {
            const err = e as { response?: { data?: { msg?: string; errors?: Record<string, string[]> } } };
            const msg =
                err.response?.data?.msg ||
                (err.response?.data?.errors && Object.values(err.response.data.errors).flat().join(' ')) ||
                'تعذر حفظ الإجازة';
            toast.error(msg, { className: 'font-cairo' });
        } finally {
            setSubmitting(false);
        }
    };

    const onSubmit = async (data: AddHolidayDialogFormValues) => {
        setSubmitting(true);
        const reasonText = buildReasonText(data);
        try {
            if (isEdit && editingHoliday) {
                if (isEmployeeRequestEdit) {
                    const st = data.status ?? 'pending';
                    if (st === 'rejected' && !(data.reject_reason || '').trim()) {
                        toast.error('يرجى إدخال سبب الرفض عند اختيار مرفوض', { className: 'font-cairo' });
                        setSubmitting(false);
                        return;
                    }
                    await apiPost({
                        endpoint: endpoints.holiday.update + editingHoliday.id,
                        body: {
                            vacation_type: data.name,
                            start_date: format(data.start_date, 'yyyy-MM-dd'),
                            end_date: format(data.end_date, 'yyyy-MM-dd'),
                            reason: reasonText,
                            status: st,
                            ...(st === 'rejected' && (data.reject_reason || '').trim()
                                ? { reject_reason: (data.reject_reason || '').trim() }
                                : {}),
                        },
                    });
                    toast.success('تم تحديث الطلب بنجاح', { className: 'font-cairo' });
                } else {
                    await apiPost({
                        endpoint: endpoints.holiday.update + editingHoliday.id,
                        body: {
                            vacation_type: data.name,
                            start_date: format(data.start_date, 'yyyy-MM-dd'),
                            end_date: format(data.end_date, 'yyyy-MM-dd'),
                            reason: reasonText,
                            status: 'approved',
                        },
                    });
                    toast.success('تم تحديث الإجازة بنجاح', { className: 'font-cairo' });
                }
            } else {
                await apiPost({
                    endpoint: endpoints.holiday.create,
                    body: {
                        vacation_type: data.name,
                        start_date: format(data.start_date, 'yyyy-MM-dd'),
                        end_date: format(data.end_date, 'yyyy-MM-dd'),
                        reason: reasonText,
                        status: 'approved',
                        is_company: true,
                    },
                });
                toast.success('تم إنشاء الإجازة بنجاح', { className: 'font-cairo' });
            }
            onSaved?.();
            onOpenChange(false);
        } catch (e: unknown) {
            const err = e as { response?: { data?: { msg?: string; errors?: Record<string, string[]> } } };
            const msg =
                err.response?.data?.msg ||
                (err.response?.data?.errors && Object.values(err.response.data.errors).flat().join(' ')) ||
                'تعذر حفظ الإجازة';
            toast.error(msg, { className: 'font-cairo' });
        } finally {
            setSubmitting(false);
        }
    };

    const quickApprove = () => {
        form.handleSubmit((data) => postUpdate(data, 'approved'))();
    };

    const quickReject = () => {
        form.handleSubmit((data) => postUpdate(data, 'rejected'))();
    };

    const title = useMemo(() => {
        if (!isEdit) return 'إنشاء إجازة';
        return isEmployeeRequestEdit ? 'مراجعة طلب إجازة' : 'تعديل إجازة';
    }, [isEdit, isEmployeeRequestEdit]);

    return (
        <Dialog open={open} onOpenChange={onOpenChange} modal>
            <DialogContent
                showCloseButton={false}
                dir="rtl"
                overlayClassName="z-[100]"
                className={cn(
                    'z-[110] max-h-[min(92vh,720px)] overflow-y-auto overflow-x-hidden',
                    'max-w-[480px] rounded-lg p-6 sm:p-8 bg-white-blue-50 font-cairo gap-0 border-[#E8E7EA]',
                )}
                onCloseAutoFocus={(e) => e.preventDefault()}
                onOpenAutoFocus={(e) => {
                    e.preventDefault();
                    const root = e.currentTarget as HTMLElement | null;
                    window.requestAnimationFrame(() => {
                        const input = root?.querySelector<HTMLInputElement>('input');
                        input?.focus({ preventScroll: true });
                    });
                }}
            >
                <DialogHeader className="flex flex-col items-stretch space-y-0">
                    <DialogTitle className="sr-only">{title}</DialogTitle>
                    <div className="flex flex-row items-center gap-2 mb-4">
                        <PlusIcon />
                        <h2 className="text-[22px] font-bold text-primery-blue-500">{title}</h2>
                    </div>
                    <div className="w-full border-b border-[#D1D1D1]" />
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6 space-y-5">
                        {isEdit && editingHoliday && (
                            <div className="rounded-lg border border-primery-blue-100 bg-primery-blue-50/60 px-3 py-2 text-sm text-primery-blue-800 text-end">
                                {editingHoliday.employeeName?.trim() ? (
                                    <>
                                        <span className="font-semibold">طالب الإجازة: </span>
                                        {editingHoliday.employeeName.trim()}
                                    </>
                                ) : editingHoliday.employeeId != null ? (
                                    <>
                                        <span className="font-semibold">طالب الإجازة: </span>
                                        موظف #{editingHoliday.employeeId}
                                    </>
                                ) : (
                                    <span>إجازة شركة / رسمية (لا يوجد موظف مرتبط)</span>
                                )}
                            </div>
                        )}

                        {isEmployeeRequestEdit && (
                            <>
                                <SelectInputForm
                                    name="status"
                                    label="حالة الطلب"
                                    placeholder="اختر الحالة"
                                    options={STATUS_OPTIONS}
                                />
                                {watchedStatus === 'rejected' && (
                                    <FormField
                                        control={form.control}
                                        name="reject_reason"
                                        render={({ field }) => (
                                            <FormItem>
                                                <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                                    سبب الرفض
                                                </FormLabel>
                                                <FormControl>
                                                    <Textarea
                                                        {...field}
                                                        rows={3}
                                                        placeholder="اذكر سبب رفض الطلب"
                                                        className="placeholder:text-white-blue-600 resize-y min-h-[80px]"
                                                    />
                                                </FormControl>
                                                <FormMessage />
                                            </FormItem>
                                        )}
                                    />
                                )}
                                <div className="flex flex-col gap-2 sm:flex-row-reverse sm:gap-3">
                                    <PrimaryButton
                                        type="button"
                                        disabled={submitting}
                                        onClick={quickApprove}
                                        className="flex-1 text-base font-semibold py-3 bg-green-700 hover:bg-green-800 border-0"
                                    >
                                        موافقة على الطلب
                                    </PrimaryButton>
                                    <SecondaryButton
                                        type="button"
                                        disabled={submitting}
                                        onClick={quickReject}
                                        className="flex-1 text-base font-semibold py-3 bg-red-50 text-red-700 border border-red-200 hover:bg-red-100"
                                    >
                                        رفض الطلب
                                    </SecondaryButton>
                                </div>
                                <p className="text-xs text-[#625E74] text-end leading-relaxed">
                                    عند الرفض، املأ حقل «سبب الرفض» ثم اضغط «رفض الطلب». يمكنك أيضاً اختيار الحالة ثم «حفظ
                                    التغييرات».
                                </p>
                            </>
                        )}

                        <FormField
                            control={form.control}
                            name="name"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-primery-blue-900 font-medium text-[15px]">اسم الإجازة</FormLabel>
                                    <FormControl>
                                        <Input
                                            {...field}
                                            placeholder="مثال: عيد الفطر"
                                            className="placeholder:text-white-blue-600"
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <DayPickerInputForm name="start_date" label="تاريخ البداية" placeholder="اختر التاريخ" />
                        <DayPickerInputForm name="end_date" label="تاريخ النهاية" placeholder="اختر التاريخ" />
                        <FormField
                            control={form.control}
                            name="reason"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-primery-blue-900 font-medium text-[15px]">السبب (اختياري)</FormLabel>
                                    <FormControl>
                                        <Textarea
                                            {...field}
                                            rows={3}
                                            placeholder={DEFAULT_REASON}
                                            className="placeholder:text-white-blue-600 resize-y min-h-[80px]"
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <div className="flex flex-row-reverse gap-3 pt-2">
                            <PrimaryButton type="submit" disabled={submitting} className="flex-1 text-base font-semibold py-3">
                                {submitting ? 'جاري الحفظ...' : isEdit ? 'حفظ التغييرات' : 'حفظ'}
                            </PrimaryButton>
                            <SecondaryButton
                                type="button"
                                className="flex-1 text-base font-semibold py-3"
                                onClick={() => onOpenChange(false)}
                            >
                                إلغاء
                            </SecondaryButton>
                        </div>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}
