import { addDays, format, getDay, startOfMonth } from 'date-fns';

/** Week starts Saturday (Saudi-style). JS: 0=Sun … 6=Sat */
function daysFromWeekStartSaturday(d: Date): number {
    return (getDay(d) + 1) % 7;
}

export function buildCalendarGrid(year: number, month0: number): Date[] {
    const monthStart = startOfMonth(new Date(year, month0, 1));
    const offset = daysFromWeekStartSaturday(monthStart);
    const gridStart = addDays(monthStart, -offset);
    const cells: Date[] = [];
    for (let i = 0; i < 42; i++) {
        cells.push(addDays(gridStart, i));
    }
    return cells;
}

export function isSameMonth(a: Date, b: Date): boolean {
    return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

export function dateKey(d: Date): string {
    return format(d, 'yyyy-MM-dd');
}

export type HolidayRangeRow = {
    id: number;
    /** vacation_type from API (used in edit form as "اسم الإجازة") */
    name: string;
    start: string;
    end: string;
    reason?: string;
    /** Requesting employee display name; null/empty when company/public holiday */
    employeeName?: string | null;
    employeeId?: number | null;
    status?: string;
    rejectReason?: string | null;
};

function datePart(v: unknown): string {
    const s = String(v ?? '').trim();
    if (!s) return '';
    return s.slice(0, 10);
}

function parseEmployeeMeta(row: Record<string, unknown>): { employeeName: string | null; employeeId: number | null } {
    const emp = row.employee;
    if (emp && typeof emp === 'object' && emp !== null) {
        const o = emp as { id?: unknown; name?: unknown };
        const n = o.name != null ? String(o.name).trim() : '';
        const eid = o.id != null && o.id !== '' ? Number(o.id) : NaN;
        return {
            employeeName: n || null,
            employeeId: Number.isFinite(eid) ? eid : null,
        };
    }
    const rawEid = row.employee_id;
    if (rawEid != null && rawEid !== '') {
        const eid = Number(rawEid);
        return { employeeName: null, employeeId: Number.isFinite(eid) ? eid : null };
    }
    return { employeeName: null, employeeId: null };
}

export function parseHolidayListRow(row: Record<string, unknown>): HolidayRangeRow | null {
    const id = Number(row.id);
    if (Number.isNaN(id)) return null;
    const name = String(row.vacation_type ?? row.name ?? row.title ?? '').trim();
    const start = datePart(row.start_date);
    const endRaw = datePart(row.end_date) || start;
    if (!start) return null;
    const reason = row.reason != null ? String(row.reason).trim() : undefined;
    const { employeeName, employeeId } = parseEmployeeMeta(row);
    const status = row.status != null ? String(row.status).trim() : undefined;
    const rejectReason =
        row.reject_reason != null && String(row.reject_reason).trim() !== ''
            ? String(row.reject_reason).trim()
            : undefined;
    return {
        id,
        name: name || 'إجازة',
        start,
        end: endRaw || start,
        reason: reason || undefined,
        employeeName,
        employeeId,
        status: status || undefined,
        rejectReason: rejectReason ?? undefined,
    };
}

export type DayMapEntry = {
    id: number;
    name: string;
    employeeName: string | null;
    status?: string;
};

/** Map yyyy-MM-dd -> display fields (last write wins for overlapping ranges) */
export function rangesToDayMap(rows: HolidayRangeRow[]): Map<string, DayMapEntry> {
    const map = new Map<string, DayMapEntry>();
    for (const row of rows) {
        let d = new Date(row.start + 'T12:00:00');
        const end = new Date(row.end + 'T12:00:00');
        if (Number.isNaN(d.getTime()) || Number.isNaN(end.getTime())) continue;
        while (d <= end) {
            const emp =
                row.employeeName && row.employeeName.trim()
                    ? row.employeeName.trim()
                    : row.employeeId != null
                      ? `موظف #${row.employeeId}`
                      : null;
            map.set(dateKey(d), {
                id: row.id,
                name: row.name,
                employeeName: emp,
                status: row.status,
            });
            d = addDays(d, 1);
        }
    }
    return map;
}
